/**
 * Normalise a string for fuzzy search:
 *  1. NFKD decomposition - collapses full-width/circled/squared compatibility
 *     chars and splits diacritics into combining marks.
 *  2. Strip combining diacritical marks → é→e, ñ→n, ü→u …
 *  3. Map Mathematical Alphanumeric Symbol code-points (U+1D400-U+1D7C3) back
 *     to their plain ASCII equivalents - covers every style BC players use:
 *     Bold, Italic, Bold Italic, Script, Bold Script, Fraktur, Double-struck,
 *     Sans-serif (regular / Bold / Italic / Bold Italic), and Monospace.
 *
 * Result is NOT lowercased - callers should chain .toLowerCase() as needed.
 */
function normalizeForSearch(s: string): string {
    if (!s) return s;
    try { s = s.normalize("NFKD"); } catch { /* ignore */ }
    // Strip combining diacritical marks
    s = s.replace(/[̀-ͯ᷀-᷿⃐-⃿]/g, "");
    // Mathematical Alphanumeric Symbols: each style has a capital block (A-Z)
    // followed (or preceded by 26 chars) by a lowercase block (a-z).
    // Format: [capitalBlockStart, lowercaseBlockStart]
    const MATH_STYLES: [number, number][] = [
        [0x1D400, 0x1D41A], // Bold
        [0x1D434, 0x1D44E], // Italic
        [0x1D468, 0x1D482], // Bold Italic
        [0x1D49C, 0x1D4B6], // Script
        [0x1D4D0, 0x1D4EA], // Bold Script   ← 𝓓𝓙 lives here
        [0x1D504, 0x1D51E], // Fraktur
        [0x1D538, 0x1D552], // Double-struck
        [0x1D56C, 0x1D586], // Bold Fraktur
        [0x1D5A0, 0x1D5BA], // Sans-serif
        [0x1D5D4, 0x1D5EE], // Sans-serif Bold
        [0x1D608, 0x1D622], // Sans-serif Italic
        [0x1D63C, 0x1D656], // Sans-serif Bold Italic
        [0x1D670, 0x1D68A], // Monospace
    ];
    return [...s].map(ch => {
        const cp = ch.codePointAt(0) ?? 0;
        if (cp < 0x1D400 || cp > 0x1D7C3) return ch;
        for (const [cap, low] of MATH_STYLES) {
            if (cp >= cap && cp < cap + 26) return String.fromCharCode(65 + cp - cap); // → A-Z
            if (cp >= low && cp < low + 26) return String.fromCharCode(97 + cp - low); // → a-z
        }
        return ch;
    }).join("");
}


function getGroupAssets(group: string): string[] {
    try {
        const w = window as unknown as Record<string, unknown>;
        const bcAssets = w.Asset as Array<{ Name?: string; Group?: { Name?: string; Family?: string } }> | undefined;
        if (!Array.isArray(bcAssets)) return [];
        const family = (Player as unknown as Record<string, unknown>).AssetFamily as string | undefined;
        return bcAssets
            .filter(a => a?.Group?.Name === group && (!family || !a.Group?.Family || a.Group.Family === family))
            .map(a => a.Name)
            .filter((n): n is string => !!n)
            .sort();
    } catch { return []; }
}

// -- Slow Leave preset storage -------------------------------------------------

const SLOW_LEAVE_PRESET_DEFAULTS = [
    { label: "Classic", intro: "smiles and gives a little wave~" },
    { label: "Warm",    intro: "gives everyone a warm hug before leaving~" },
    { label: "Quiet",   intro: "" },
    { label: "Sleepy",  intro: "yawns softly and stretches~" },
    { label: "Playful", intro: "bounces happily and waves her tail~" },
    { label: "Bratty",  intro: "stretches dramatically and rolls her eyes~ Fine, leaving. Don't miss me too much." },
    { label: "Custom",  intro: "" },
];

function extractIntroFromSeq(seq: string): string {
    for (const step of seq.split("|")) {
        const s = step.trim();
        if (s.startsWith("*")) {
            const atIdx = s.lastIndexOf("@");
            const raw = atIdx > 0 ? s.slice(0, atIdx).trim() : s;
            return raw.replace(/^\*/, "").trim();
        }
    }
    return "";
}

function getSlowLeavePresets(): Array<{ label: string; intro: string }> {
    try {
        const raw = localStorage.getItem("EBC_slowLeavePresets");
        if (raw) {
            const parsed = JSON.parse(raw) as Array<{ label: string; intro?: string; seq?: string }>;
            if (Array.isArray(parsed) && parsed.length > 0) {
                // Migrate old seq-based format to intro format
                const migrated = parsed.map(p => ({
                    label: p.label,
                    intro: p.intro !== undefined ? p.intro : (p.seq ? extractIntroFromSeq(p.seq) : ""),
                }));
                // Additive migration: append any new defaults not yet in the stored list
                for (const def of SLOW_LEAVE_PRESET_DEFAULTS) {
                    if (!migrated.find(p => p.label === def.label)) migrated.push({ ...def });
                }
                return migrated;
            }
        }
    } catch { /* ignore */ }
    return SLOW_LEAVE_PRESET_DEFAULTS.map(p => ({ ...p }));
}

function saveSlowLeavePresets(v: Array<{ label: string; intro: string }>): void {
    try { localStorage.setItem("EBC_slowLeavePresets", JSON.stringify(v)); } catch { /* ignore */ }
}

